# area: descriptors_properties
# hypothesis: A module-level generic decorator on a descriptor's __set__ keeps the setter signature, so mypy and ty reject a str argument while CPython runs the valid calls.
from typing import reveal_type


def passthrough[F](fn: F) -> F:
    return fn


class Desc:
    @passthrough
    def __set__(self, obj: object, value: int) -> None:
        print('set', value)

    def __delete__(self, obj: object) -> None:
        print('delete')


class Host:
    attr = Desc()


h = Host()
h.attr = 5
Desc.__set__(Desc(), h, 5)
Desc.__delete__(Desc(), h)
reveal_type(Desc.__set__)


def probe(d: Desc, host: Host) -> None:
    d.__set__(host, 'bad')  # expect-error
    print('probe done')


probe(Desc(), h)
